#define HT_BITS 17
#define HT_SIZE (1 << HT_BITS)
#define HT_MASK (HT_SIZE - 1)
#define NTHREADS 4

typedef struct {
    uint64_t hash;
    uint64_t key8;
    uint32_t offset;
    uint32_t count;
    uint16_t len;
} Entry;

typedef struct {
    Entry htable[HT_SIZE];
    char *arena;
    size_t arena_used;
    size_t arena_cap;
    const unsigned char *data;
    size_t start;
    size_t end;
} ThreadCtx;

static ThreadCtx tctx[NTHREADS];
static uint8_t is_ws_lut[256];
static uint8_t lower_lut[256];

static void init_luts(void) {
    for (int i = 0; i < 256; i++) {
        is_ws_lut[i] = (i == ' ' || i == '\n' || i == '\t' || i == '\r' || i == '\v' || i == '\f') ? 1 : 0;
        lower_lut[i] = (i >= 'A' && i <= 'Z') ? (uint8_t)(i + 32) : (uint8_t)i;
    }
}

static inline void arena_init(ThreadCtx *ctx, size_t cap) {
    ctx->arena_cap = cap;
    ctx->arena = (char *)malloc(cap);
    ctx->arena_used = 0;
}

static inline uint32_t arena_alloc(ThreadCtx *ctx, const char *s, size_t len) {
    if (ctx->arena_used + len > ctx->arena_cap) {
        size_t new_cap = ctx->arena_cap * 2;
        if (new_cap < ctx->arena_used + len) new_cap = ctx->arena_used + len + 1024 * 1024;
        ctx->arena = (char *)realloc(ctx->arena, new_cap);
        ctx->arena_cap = new_cap;
    }
    uint32_t off = (uint32_t)ctx->arena_used;
    memcpy(ctx->arena + off, s, len);
    ctx->arena_used += len;
    return off;
}

static inline void ht_insert(ThreadCtx *ctx, uint64_t h, uint64_t key8, const char *w, uint16_t len, uint32_t add_count) {
    uint32_t idx = (uint32_t)h & HT_MASK;
    Entry *ht = ctx->htable;
    while (1) {
        Entry *e = &ht[idx];
        if (e->count == 0) {
            e->hash = h;
            e->key8 = key8;
            e->len = len;
            e->count = add_count;
            e->offset = arena_alloc(ctx, w, len);
            return;
        }
        if (len <= 8) {
            if (e->len == len && e->key8 == key8) {
                e->count += add_count;
                return;
            }
        } else {
            if (e->hash == h && e->len == len && memcmp(ctx->arena + e->offset, w, len) == 0) {
                e->count += add_count;
                return;
            }
        }
        idx = (idx + 1) & HT_MASK;
    }
}

static void *worker(void *arg) {
    ThreadCtx *ctx = (ThreadCtx *)arg;
    const unsigned char *p = ctx->data + ctx->start;
    const unsigned char *end = ctx->data + ctx->end;
    char wbuf[4096];

    while (p < end) {
        while (p < end && is_ws_lut[*p]) p++;
        if (p >= end) break;

        uint64_t h = 14695981039346656037ULL;
        uint64_t key8 = 0;
        uint16_t len = 0;

        while (p < end && !is_ws_lut[*p]) {
            uint8_t c = lower_lut[*p++];
            if (len < 8) {
                key8 |= ((uint64_t)c) << (len * 8);
            }
            if (len < sizeof(wbuf)) {
                wbuf[len++] = (char)c;
            }
            h ^= c;
            h *= 1099511628211ULL;
        }
        h ^= h >> 33;
        ht_insert(ctx, h, key8, wbuf, len, 1);
    }
    return NULL;
}

static const char *g_arena0;

static int cmp_entry(const void *a, const void *b) {
    const Entry *ea = *(const Entry * const *)a;
    const Entry *eb = *(const Entry * const *)b;
    if (ea->count != eb->count) {
        return (eb->count > ea->count) ? 1 : -1;
    }
    uint16_t min_len = ea->len < eb->len ? ea->len : eb->len;
    int cmp = memcmp(g_arena0 + ea->offset, g_arena0 + eb->offset, min_len);
    if (cmp != 0) return cmp;
    return (int)ea->len - (int)eb->len;
}

int run_wf(void) {
    init_luts();
    struct stat st;
    unsigned char *data = NULL;
    size_t size = 0;
    int is_mmap = 0;

    if (fstat(0, &st) == 0 && S_ISREG(st.st_mode) && st.st_size > 0) {
        size = (size_t)st.st_size;
        void *m = mmap(NULL, size, PROT_READ, MAP_PRIVATE, 0, 0);
        if (m != MAP_FAILED) {
            data = (unsigned char *)m;
            is_mmap = 1;
        }
    }

    if (!is_mmap) {
        size_t cap = 65536;
        data = (unsigned char *)malloc(cap);
        ssize_t n;
        while ((n = read(0, data + size, cap - size)) > 0) {
            size += (size_t)n;
            if (size == cap) {
                cap *= 2;
                data = (unsigned char *)realloc(data, cap);
            }
        }
    }

    memset(tctx[0].htable, 0, sizeof(tctx[0].htable));
    arena_init(&tctx[0], 512 * 1024);

    if (size >= 1048576) {
        pthread_t threads[NTHREADS];
        for (int t = 0; t < NTHREADS; t++) {
            if (t > 0) {
                memset(tctx[t].htable, 0, sizeof(tctx[t].htable));
                arena_init(&tctx[t], 256 * 1024);
            }
            size_t s = (size * (size_t)t) / NTHREADS;
            size_t e = (size * (size_t)(t + 1)) / NTHREADS;
            if (t > 0) {
                while (s < size && !is_ws_lut[data[s]]) s++;
            }
            if (t < NTHREADS - 1) {
                while (e < size && !is_ws_lut[data[e]]) e++;
            }
            if (s > e) s = e;
            tctx[t].data = data;
            tctx[t].start = s;
            tctx[t].end = e;
            if (t > 0) {
                pthread_create(&threads[t], NULL, worker, &tctx[t]);
            }
        }
        worker(&tctx[0]);
        for (int t = 1; t < NTHREADS; t++) {
            pthread_join(threads[t], NULL);
            Entry *ht = tctx[t].htable;
            const char *ar = tctx[t].arena;
            for (int i = 0; i < HT_SIZE; i++) {
                if (ht[i].count > 0) {
                    ht_insert(&tctx[0], ht[i].hash, ht[i].key8, ar + ht[i].offset, ht[i].len, ht[i].count);
                }
            }
            free(tctx[t].arena);
        }
    } else if (size > 0) {
        tctx[0].data = data;
        tctx[0].start = 0;
        tctx[0].end = size;
        worker(&tctx[0]);
    }

    if (is_mmap) {
        munmap(data, size);
    } else {
        free(data);
    }

    g_arena0 = tctx[0].arena;
    Entry *top[10];
    int top_n = 0;
    Entry *ht0 = tctx[0].htable;

    for (int i = 0; i < HT_SIZE; i++) {
        Entry *e = &ht0[i];
        if (e->count == 0) continue;
        if (top_n < 10) {
            top[top_n++] = e;
            for (int k = top_n - 1; k > 0; k--) {
                if (cmp_entry(&top[k], &top[k - 1]) < 0) {
                    Entry *tmp = top[k]; top[k] = top[k - 1]; top[k - 1] = tmp;
                } else break;
            }
        } else if (e->count > top[9]->count || (e->count == top[9]->count && cmp_entry(&e, &top[9]) < 0)) {
            top[9] = e;
            for (int k = 9; k > 0; k--) {
                if (cmp_entry(&top[k], &top[k - 1]) < 0) {
                    Entry *tmp = top[k]; top[k] = top[k - 1]; top[k - 1] = tmp;
                } else break;
            }
        }
    }

    char out_buf[4096];
    int out_pos = 0;
    for (int j = 0; j < top_n; j++) {
        Entry *e = top[j];
        memcpy(out_buf + out_pos, g_arena0 + e->offset, e->len);
        out_pos += e->len;
        out_pos += snprintf(out_buf + out_pos, 32, " %u\n", e->count);
    }
    if (out_pos > 0) {
        ssize_t unused = write(1, out_buf, (size_t)out_pos);
        (void)unused;
    }
    free(tctx[0].arena);
    return 0;
}

